(()=>{const box=document.querySelector('#club-cards'),q=document.querySelector('#club-find'),cnt=document.querySelector('#club-count');if(!box||!q||!window.CLUBS)return;const n=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const el=(t,x,c)=>{const e=document.createElement(t);if(x)e.textContent=x;if(c)e.className=c;return e};
const F=['Adresse du dojo','Créneaux','Publics','Tarifs (datés)','Contact public','Itinéraire'];
function render(){const v=n(q.value),l=window.CLUBS.filter(c=>n(c[0]+' '+c[1]).includes(v));box.replaceChildren();cnt.textContent=l.length+' club'+(l.length>1?'s':'');for(const [name,city,url] of l){const a=el('article',null,'club-card');a.append(el('p',city,'eyebrow blue'),el('h3',name));const dl=el('dl');const add=(k,v,ok)=>{dl.append(el('dt',k));const d=el('dd');if(url&&k==='Site'){const x=el('a','Voir le site ↗');x.href=url;x.target='_blank';x.rel='noopener';d.append(x)}else d.append(el('span',v||'À confirmer',ok?'':'tbc'));dl.append(d)};add('Site',url?'':'À confirmer');for(const k of F)add(k);a.append(dl);box.append(a)}if(!l.length)box.append(el('p','Aucun club trouvé. Essayez une autre commune.','journal-empty'))}
q.addEventListener('input',render);render()})();
